CREATE TABLE `RequisitoDocumento` (`id` INTEGER NOT NULL AUTO_INCREMENT, `usuarioId` INTEGER NOT NULL, `codigo` VARCHAR(80) NOT NULL, `nombre` VARCHAR(191) NOT NULL, `obligatorio` BOOLEAN NOT NULL DEFAULT true, `activo` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `RequisitoDocumento_usuarioId_codigo_key` (`usuarioId`,`codigo`), INDEX `RequisitoDocumento_usuarioId_activo_idx` (`usuarioId`,`activo`), CONSTRAINT `RequisitoDocumento_usuarioId_fkey` FOREIGN KEY (`usuarioId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DocumentoVersion` (`id` VARCHAR(30) NOT NULL, `requisitoId` INTEGER NOT NULL, `archivoId` VARCHAR(30) NOT NULL, `version` INTEGER NOT NULL, `estado` ENUM('PENDIENTE_CARGA','EN_REVISION','AUTORIZADO','RECHAZADO','REQUIERE_CORRECCION','VENCIDO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE_CARGA', `comentario` VARCHAR(1000) NULL, `cargadoPorId` INTEGER NOT NULL, `revisadoPorId` INTEGER NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `DocumentoVersion_requisitoId_version_key` (`requisitoId`,`version`), INDEX `DocumentoVersion_requisitoId_estado_createdAt_idx` (`requisitoId`,`estado`,`createdAt`), CONSTRAINT `DocumentoVersion_requisitoId_fkey` FOREIGN KEY (`requisitoId`) REFERENCES `RequisitoDocumento` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `DocumentoVersion_archivoId_fkey` FOREIGN KEY (`archivoId`) REFERENCES `Archivo` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `DocumentoVersion_cargadoPorId_fkey` FOREIGN KEY (`cargadoPorId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `DocumentoVersion_revisadoPorId_fkey` FOREIGN KEY (`revisadoPorId`) REFERENCES `Usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
